fn em_list_all_human() {
    let dir = setup_fixture("setup-emergence-states");
    let out = novel()
        .args(["emergence", "list", "1"])
        .arg("--path").arg(dir.path())
        .assert().success().get_output().clone();
    assert!(String::from_utf8_lossy(&out.stdout).contains("em-1-7"));
    assert!(String::from_utf8_lossy(&out.stdout).contains("archived"));
}


/// spec scenario: List emergences filtered by status
/// source: specs/emergence-management/spec.md
#[test]
fn em_list_filter_rated() {
    let dir = setup_fixture("setup-emergence-states");
    let out = novel()
        .args(["emergence", "list", "1", "--status", "rated", "--json"])
        .arg("--path").arg(dir.path())
        .assert().success().get_output().clone();
    let actual: Value = serde_json::from_slice(&out.stdout).expect("stdout 应为单一合法 JSON");
    assert_eq!(actual["emergences"].as_array().expect("字段 emergences 应为数组").len(), 1);
}


