/// spec scenario: Structured error format
/// source: specs/emergence-management/spec.md
#[test]
fn em_contract_structured_error() {
    let dir = setup_fixture("setup-emergence-states");
    let out = novel()
        .args(["emergence", "get", "em-1-99", "--json"])
        .arg("--path").arg(dir.path())
        .assert().code(6).get_output().clone();
    let actual: Value = serde_json::from_slice(&out.stdout).expect("stdout 应为合法 JSON");
    assert_eq!(actual["errorId"].as_str().unwrap(), "emergence_not_found");
    assert!(actual["message"].as_str().map_or(false, |m| !m.is_empty()));
    assert!(actual.get("schemaVersion").is_some(), "缺字段 schemaVersion");
    assert!(actual.get("status").is_some(), "缺字段 status");
    assert!(actual.get("errorId").is_some(), "缺字段 errorId");
    assert!(actual.get("category").is_some(), "缺字段 category");
    assert!(actual.get("exitCode").is_some(), "缺字段 exitCode");
    assert!(actual.get("message").is_some(), "缺字段 message");
}


/// spec scenario: emergence get 成功路径契约测试覆盖 JSON schema
/// source: specs/emergence-management/spec.md
#[test]
fn em_contract_get_json_schema() {
    let dir = setup_fixture("setup-emergence-world");
    let out = novel()
        .args(["emergence", "get", "em-1-1", "--json"])
        .arg("--path").arg(dir.path())
        .assert().success().get_output().clone();
    let actual: Value = serde_json::from_slice(&out.stdout).expect("stdout 应为单一合法 JSON");
    assert!(actual.get("schemaVersion").is_some(), "缺字段 schemaVersion");
    assert!(actual.get("id").is_some(), "缺字段 id");
    assert!(actual.get("volumeId").is_some(), "缺字段 volumeId");
    assert!(actual.get("title").is_some(), "缺字段 title");
    assert!(actual.get("description").is_some(), "缺字段 description");
    assert!(actual.get("status").is_some(), "缺字段 status");
    assert!(actual.get("discoveredAt").is_some(), "缺字段 discoveredAt");
    assert!(actual.get("createdAt").is_some(), "缺字段 createdAt");
    assert!(actual.get("updatedAt").is_some(), "缺字段 updatedAt");
    assert_eq!(actual["status"].as_str().unwrap_or(""), "pending");
    assert_eq!(actual["volumeId"].as_i64().expect("字段 volumeId 应为数值"), 1);
}


